<script setup lang="ts">
import {ref,shallowRef,computed,onMounted,onBeforeUnmount,nextTick,watch} from 'vue'
import type {PDFDocumentProxy,PageViewport} from 'pdfjs-dist'
import {TextLayer} from '../lib/pdf'
import type {Annotation} from '../types'
import {uniqueSelectionRects} from '../lib/readerContext'
const props=defineProps<{pdf:PDFDocumentProxy;page:number;scale:number;rotation:number;annotations:Annotation[];regionMode:boolean}>()
const emit=defineEmits<{selection:[value:{quote:string;rects:number[][];page:number;anchor?:{left:number;right:number;top:number;bottom:number}}];visible:[page:number];warning:[text:string];annotation:[value:Annotation]}>()
const root=ref<HTMLElement>(),canvas=ref<HTMLCanvasElement>(),text=ref<HTMLElement>(),size=ref({width:612,height:792}),failure=ref(''),region=ref<{x:number;y:number;w:number;h:number}|null>(null)
const viewport=shallowRef<PageViewport>();let task:any,layer:any,observer:IntersectionObserver,visible=false,disposed=false,generation=0,start:{x:number;y:number}|null=null
const dimensions=computed(()=>({width:size.value.width*props.scale+'px',height:size.value.height*props.scale+'px','--scale-factor':props.scale,'--total-scale-factor':props.scale}))
async function render(){const n=++generation,old=task;old?.cancel();layer?.cancel();try{if(old)await old.promise.catch(()=>{});if(!visible||disposed||n!==generation)return;const p=await props.pdf.getPage(props.page);viewport.value=p.getViewport({scale:props.scale,rotation:props.rotation});const base=p.getViewport({scale:1,rotation:props.rotation});size.value={width:base.width,height:base.height};await nextTick();if(!visible||disposed||n!==generation||!canvas.value||!text.value)return;const ratio=Math.min(devicePixelRatio||1,2);canvas.value.width=Math.ceil(viewport.value.width*ratio);canvas.value.height=Math.ceil(viewport.value.height*ratio);task=p.render({canvas:canvas.value,canvasContext:canvas.value.getContext('2d')!,viewport:viewport.value,transform:ratio===1?undefined:[ratio,0,0,ratio,0,0]});await task.promise;if(!visible||disposed||n!==generation)return;const content=await p.getTextContent();if(disposed||n!==generation||!text.value)return;text.value.replaceChildren();layer=new TextLayer({textContentSource:content,container:text.value,viewport:viewport.value});await layer.render();failure.value=''}catch(e){if((e as Error).name!=='RenderingCancelledException'&&(e as Error).name!=='AbortException')failure.value='此页渲染失败，请重新打开论文。'}}
function quad(r:DOMRect){if(!root.value||!viewport.value)return [];const b=root.value.getBoundingClientRect();return [[r.left-b.left,r.top-b.top],[r.right-b.left,r.top-b.top],[r.left-b.left,r.bottom-b.top],[r.right-b.left,r.bottom-b.top]].flatMap(([x,y])=>viewport.value!.convertToPdfPoint(x!,y!))}
function select(e?:MouseEvent){if(props.regionMode)return;if(e&&!getSelection()?.toString().trim()&&root.value&&viewport.value){const b=root.value.getBoundingClientRect(),point=viewport.value.convertToPdfPoint(e.clientX-b.left,e.clientY-b.top);const a=props.annotations.find(a=>a.rects.some(r=>{const xs=r.filter((_,i)=>i%2===0),ys=r.filter((_,i)=>i%2===1);return point[0]!>=Math.min(...xs)&&point[0]!<=Math.max(...xs)&&point[1]!>=Math.min(...ys)&&point[1]!<=Math.max(...ys)}));if(a){emit('annotation',a);return}}const s=getSelection();if(!s?.rangeCount||!s.toString().trim()||!text.value?.contains(s.anchorNode))return;if(!text.value.contains(s.focusNode)){emit('warning','跨页选区请分开摘录，以保留准确的页面位置。');return}const rects=uniqueSelectionRects(Array.from(s.getRangeAt(0).getClientRects()).filter(r=>r.width>2&&r.height>2).map(quad));if(rects.length&&root.value){const bounds=root.value.getBoundingClientRect(),r=s.getRangeAt(0).getBoundingClientRect();emit('selection',{quote:s.toString(),rects,page:props.page,anchor:{left:r.left-bounds.left,right:r.right-bounds.left,top:r.top-bounds.top,bottom:r.bottom-bounds.top}})}}
function selectionChanged(){select()}
function rectStyle(q:number[]){if(!viewport.value)return {};const points=[];for(let i=0;i<q.length;i+=2)points.push(viewport.value.convertToViewportPoint(q[i]!,q[i+1]!));const xs=points.map(p=>p[0]!),ys=points.map(p=>p[1]!);return {left:Math.min(...xs)+'px',top:Math.min(...ys)+'px',width:Math.max(...xs)-Math.min(...xs)+'px',height:Math.max(...ys)-Math.min(...ys)+'px'}}
function down(e:PointerEvent){if(!root.value)return;const b=root.value.getBoundingClientRect();start={x:e.clientX-b.left,y:e.clientY-b.top};region.value={...start,w:0,h:0};(e.currentTarget as HTMLElement).setPointerCapture(e.pointerId)}
function move(e:PointerEvent){if(!start||!root.value)return;const b=root.value.getBoundingClientRect(),x=Math.max(0,Math.min(b.width,e.clientX-b.left)),y=Math.max(0,Math.min(b.height,e.clientY-b.top));region.value={x:Math.min(x,start.x),y:Math.min(y,start.y),w:Math.abs(x-start.x),h:Math.abs(y-start.y)}}
function end(){if(region.value&&root.value){const r=region.value,b=root.value.getBoundingClientRect();if(r.w>8&&r.h>8)emit('selection',{quote:'区域批注',rects:[quad(new DOMRect(b.left+r.x,b.top+r.y,r.w,r.h))],page:props.page})}start=null;region.value=null}
onMounted(()=>{document.addEventListener('selectionchange',selectionChanged);observer=new IntersectionObserver(entries=>{const e=entries[0];if(!e)return;visible=e.isIntersecting;if(visible)void render();else{generation++;task?.cancel();layer?.cancel();if(canvas.value){canvas.value.width=0;canvas.value.height=0}text.value?.replaceChildren()}},{root:root.value?.closest('.pdf-scroll-area'),rootMargin:'500px'});if(root.value)observer.observe(root.value)})
watch(()=>[props.scale,props.rotation],()=>{if(visible)void render()})
onBeforeUnmount(()=>{document.removeEventListener('selectionchange',selectionChanged);disposed=true;generation++;observer?.disconnect();task?.cancel();layer?.cancel()})
</script>
<template><div ref="root" class="pdf-paper reading-pdf-page" :data-page="page" :style="dimensions" @mouseup="select"><canvas ref="canvas" :style="{width:'100%',height:'100%'}"/><div ref="text" class="textLayer"></div><div class="annotation-overlay"><template v-for="a in annotations" :key="a.id"><div v-for="(r,i) in a.rects" :key="i" class="pdf-annotation" :class="a.type" :style="{...rectStyle(r),'--annotation-color':a.color}" :title="a.comment||a.quote"/></template></div><div v-if="regionMode" class="region-capture" @pointerdown="down" @pointermove="move" @pointerup="end"><div v-if="region" class="region-rectangle" :style="{left:region.x+'px',top:region.y+'px',width:region.w+'px',height:region.h+'px'}"/></div><p v-if="failure" role="alert">{{failure}}</p></div></template>
<style scoped>.reading-pdf-page{margin:0 auto 24px;scroll-margin-top:20px;contain:layout style}.reading-pdf-page>p{position:absolute;top:20px;left:20px;color:#a83d57}</style>
